  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('like god son make:psv:pp',cases['7-3']['analysis'])
  self.assertIn('as i thus say:may',cases['7-9']['analysis'])
  self.assertIn('first for his/own sin:pl',cases['7-27']['analysis'])
  self.assertIn('with they fault find:cv',cases['8-8']['analysis'])
  self.assertIn('ipl they:a regard:neg:pa',cases['8-9']['analysis'])
  self.assertIn('ipl to they god be:fu',cases['8-10']['analysis'])
  self.assertIn('kjv_table_furniture',cases['9-2']['analysis'])
  self.assertIn('kjv_covenant table:pl',cases['9-4']['analysis'])
  self.assertIn('once every year',cases['9-7']['analysis'])
  self.assertIn('kjv_testator_hebrews death be:must',cases['9-16']['analysis'])
  self.assertIn('while kjv_testator_hebrews live:pr',cases['9-17']['analysis'])
  self.assertIn('almost all thing:pl',cases['9-22']['analysis'])
  self.assertIn('second time without sin',cases['9-28']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),4)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
